export let HLEG435;
export { inBox435 }; // lu par Quêtes › Légendes (React)


/* Huit légendes, invisibles tant que Hoenn n’est pas ouverte (Maître de Johto en Campagne ; ouvert en Mode Libre).
   Chacune : un combat (Combats › Après-jeu) puis une capture (Quêtes › Légendes) soumise à une quête et à une condition propre. */
export function V435_0() {
  return { hleg: [] };
}


export function v435Clean(p) {
  const o = V435_0();
  if (p && Array.isArray(p.hleg)) o.hleg = [...new Set(p.hleg.filter(id => HLEG435.some(L => L.id === id)))];
  return o;
}


export function etapes435(L) {
  return [
    { ok: hlOk435(L.id), t: `Vaincre ${L.n} (Combats › Après-jeu)` },
    ...(isCamp() ? [{ ok: L.pre ? L.pre() : nbH435() >= L.badges, t: L.preT || `Obtenir ${L.badges} badges de Hoenn` }] : []),
    ...(isCamp() ? L.quete.map(([f, t]) => ({ ok: !!f(), t })) : [])
  ];
}


export function lock435(k, D) {
  const L = hlOf435(k);
  if (!L) return null;
  if (!hoennOuvert()) return 'Hoenn s’ouvre après votre titre de Maître de Johto.';
  if (D.cap435) {
    if (inBox435(L.id)) return `${L.n} est déjà dans votre Box.`;
    const e = etapes435(L).find(x => !x.ok);
    return e ? `Quête légendaire : ${e.t} d’abord.` : null;
  }
  if (!isCamp()) return null;
  if (L.pre ? !L.pre() && !(hlOk435(L.id)) : nbH435() < L.badges) return L.pre ? `${L.preT} d’abord.` : `Il faut ${L.badges} badges de Hoenn pour affronter ${L.n}.`;
  return null;
}

const hlOk435 = id => (PROFILE.hleg || []).includes(id);


const inBox435 = id => (PROFILE.box || []).includes(id);


const nbH435 = () => (PROFILE.hoenn || []).length;


const ballOk435 = (...k) => k.includes(CAP_K);


const escorteKO435 = (S, L) => S.units.filter(x => x.side === 'e' && x.sp !== L.id).every(x => x.ko);


const caseMark435 = (S, e, mk) => {
  const t = S.tiles && S.tiles[uk(e)];
  return !!(t && t.mark && t.mark.k === mk);
};

const hlOf435 = k => {
  const D = SCEN[k];
  return D && (D.hleg435 || D.cap435) ? HLEG435.find(L => L.id === (D.hleg435 || D.cap435)) : null;
};

